// Keyed "family:profile" — the class talents a profile adds back.
export const TOP_EXP_PROFILE_OVERRIDES: Readonly<Record<string, FlatMap>> = {
  "beginner:t35": {
    "EXP Multi": 4.43337649846551e+23,
    "EXP Multi / ➕ Additive Pool": 806990.6757841283,
    "EXP Multi / ➕ Additive Pool / Lucky Charms (Talent 35)": 538.9489782256853,
    "EXP Multi / ➕ Additive Pool / Lucky Charms (Talent 35) / EXP LUK curve": 1.196187621216071,
    "EXP Multi / ➕ Additive Pool / Lucky Charms (Talent 35) / Talent 35": 811,
  },
};

// class key → [family, talent profile]
export const TOP_EXP_CLASS_PROFILE: Readonly<Record<string, readonly [string, string]>> = {"Beginner":["beginner","base"],"Journeyman":["beginner","base"],"Maestro":["beginner","t35"],"Voidwalker":["beginner","t35"],"Warrior":["warrior","base"],"Barbarian":["warrior","base"],"Blood_Berserker":["warrior","base"],"Death_Bringer":["warrior","base"],"Squire":["warrior","base"],"Divine_Knight":["warrior","base"],"Archer":["archer","base"],"Bowman":["archer","base"],"Siege_Breaker":["archer","base"],"Hunter":["archer","base"],"Beast_Master":["archer","base"],"Wind_Walker":["archer","base"],"Mage":["mage","base"],"Shaman":["mage","base"],"Bubonic_Conjuror":["mage","base"],"Arcane_Cultist":["mage","base"],"Wizard":["mage","base"],"Elemental_Sorcerer":["mage","base"],"Royal_Guardian":["warrior","base"]};

// Family used when no class is known (the highest-reaching one).
export const TOP_EXP_DEFAULT_FAMILY = "mage";

/** The top EXP Multi reference for a class — its family's base merged with its profile. */
export function topExpFlatForClass(classKey: string | null | undefined): FlatMap {
  const [family, profile] = (classKey && TOP_EXP_CLASS_PROFILE[classKey]) || [TOP_EXP_DEFAULT_FAMILY, "base"];
  const base = TOP_EXP_FAMILY_FLAT[family] ?? TOP_EXP_FAMILY_FLAT[TOP_EXP_DEFAULT_FAMILY];
  const override = TOP_EXP_PROFILE_OVERRIDES[`${family}:${profile}`];
  return override ? { ...base, ...override } : base;
}
